import { useCallback, useEffect, useRef, useState } from 'react'
import { Link } from 'react-router-dom'
import { Helmet } from 'react-helmet-async'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { buttonVariants } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import TopNav from '../components/TopNav'
import { trackEvent } from '../lib/analytics'
import { useRouteMeta } from '../lib/useRouteMeta'

// Product tour slides. Images are generated by launch/media/render.sh + convert-web.mjs
// into public/demo/NN.webp (1270w) and NN@2x.webp (2540w).
const SLIDES = [
  { title: 'One creative workspace for teams and agents', description: 'Bring any harness and your own servers. See every agent at work, learn together, and track every run.' },
  { title: 'Delegate like email', description: 'Send a task, follow every tool call, reply mid-task to steer, and close the session when it is done.' },
  { title: 'Your harness, your servers', description: 'Claude Code, Codex, Gemini, OpenCode, Pi, or the agent you built yourself, running on your own machines.' },
  { title: 'Secure by design', description: 'Your repo and model API keys never leave your machine. Transcripts are encrypted before upload.' },
  { title: 'Planner', description: 'Split a big goal into phases, each handled by the right agent, with your approval in between.' },
  { title: 'Supervisor', description: 'When a task goes quiet, a second session inspects the terminal, unblocks it or escalates.' },
  { title: 'Notes', description: 'Write specs together, get an agent critique, and turn the note into a task with full context.' },
  { title: 'Memory & Skills', description: 'Decisions and conventions become shared memory; reusable skills sync to every agent.' },
  { title: 'Observe, govern, track', description: 'Outcomes, time to done, tool calls, tokens and feedback, per agent and per day, across every harness.' },
  { title: 'Get started in two minutes', description: 'Install tsq, sign in, and send your first task.' },
]

const slideSrc = (i: number, suffix = '') => `/demo/${String(i + 1).padStart(2, '0')}${suffix}.webp`

function indexFromHash(): number {
  const n = Number(window.location.hash.slice(1))
  return Number.isInteger(n) && n >= 1 && n <= SLIDES.length ? n - 1 : 0
}

export default function Demo() {
  const meta = useRouteMeta('/demo')
  const [index, setIndex] = useState(indexFromHash)
  const touchStartX = useRef<number | null>(null)
  const last = SLIDES.length - 1

  const go = useCallback((next: number) => {
    const clamped = Math.max(0, Math.min(last, next))
    setIndex(clamped)
    window.history.replaceState(null, '', `#${clamped + 1}`)
  }, [last])

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.target instanceof HTMLElement && e.target.closest('input, textarea, [contenteditable="true"]')) return
      if (e.key === 'ArrowRight' || e.key === 'PageDown') { e.preventDefault(); go(index + 1) }
      else if (e.key === 'ArrowLeft' || e.key === 'PageUp') { e.preventDefault(); go(index - 1) }
      else if (e.key === 'Home') { e.preventDefault(); go(0) }
      else if (e.key === 'End') { e.preventDefault(); go(last) }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [go, index, last])

  useEffect(() => {
    const onHash = () => setIndex(indexFromHash())
    window.addEventListener('hashchange', onHash)
    return () => window.removeEventListener('hashchange', onHash)
  }, [])

  const slide = SLIDES[index]

  return (
    <div className="min-h-screen bg-background">
      <Helmet>
        <title>{meta.title}</title>
        <meta name="description" content={meta.description} />
        <link rel="canonical" href="https://tasksquad.ai/demo" />
      </Helmet>

      <div className="max-w-[1100px] mx-auto px-4 sm:px-6 pt-[calc(2.5rem+env(safe-area-inset-top,0px))] sm:pt-16 pb-16">
        <TopNav source="demo_nav" />

        <div className="mb-6 sm:mb-8">
          <h1 className="text-3xl sm:text-4xl font-bold mb-2">Product tour</h1>
          <p className="text-muted-foreground">
            A quick walk through TaskSquad. Use the arrows or your keyboard (← →) to move between slides.
          </p>
        </div>

        <section
          role="region"
          aria-roledescription="carousel"
          aria-label="TaskSquad product tour"
          // Cap the width by viewport height so the whole window (chrome + slide + controls) fits on screen.
          style={{ maxWidth: 'calc((100svh - 150px) * 1270 / 760)' }}
          className="mx-auto rounded-xl border bg-card shadow-[0_24px_60px_-20px_rgba(15,17,23,0.25)] overflow-hidden"
        >
          {/* Window chrome */}
          <div className="flex items-center gap-2 h-10 px-4 border-b bg-muted/50">
            <span className="h-3 w-3 rounded-full bg-[#FF5F57]" />
            <span className="h-3 w-3 rounded-full bg-[#FEBC2E]" />
            <span className="h-3 w-3 rounded-full bg-[#28C840]" />
            <span className="ml-3 text-xs text-muted-foreground truncate">tasksquad.ai — Product tour</span>
            <span className="ml-auto text-xs font-medium text-muted-foreground tabular-nums" aria-hidden="true">
              {index + 1} / {SLIDES.length}
            </span>
          </div>

          {/* Slides */}
          <div
            className="relative aspect-[1270/760] bg-muted/30 select-none"
            onTouchStart={e => { touchStartX.current = e.touches[0].clientX }}
            onTouchEnd={e => {
              if (touchStartX.current === null) return
              const dx = e.changedTouches[0].clientX - touchStartX.current
              if (Math.abs(dx) > 40) go(index + (dx < 0 ? 1 : -1))
              touchStartX.current = null
            }}
          >
            {SLIDES.map((s, i) => {
              // Mount the current slide and its neighbours so moving between them is instant.
              if (Math.abs(i - index) > 1) return null
              return (
                <img
                  key={i}
                  src={slideSrc(i)}
                  srcSet={`${slideSrc(i)} 1270w, ${slideSrc(i, '@2x')} 2540w`}
                  sizes="(max-width: 1100px) 100vw, 1052px"
                  width={1270}
                  height={760}
                  alt={`${s.title}. ${s.description}`}
                  aria-hidden={i !== index}
                  loading={i === index ? 'eager' : 'lazy'}
                  decoding="async"
                  draggable={false}
                  className={cn(
                    'absolute inset-0 h-full w-full object-contain transition-opacity duration-300',
                    i === index ? 'opacity-100' : 'opacity-0 pointer-events-none',
                  )}
                />
              )
            })}

            <button
              type="button"
              onClick={() => go(index - 1)}
              disabled={index === 0}
              aria-label="Previous slide"
              className="hidden sm:flex absolute left-3 top-1/2 -translate-y-1/2 h-11 w-11 items-center justify-center rounded-full border bg-background/90 shadow-md backdrop-blur transition hover:bg-background disabled:opacity-0"
            >
              <ChevronLeft className="h-5 w-5" />
            </button>
            <button
              type="button"
              onClick={() => go(index + 1)}
              disabled={index === last}
              aria-label="Next slide"
              className="hidden sm:flex absolute right-3 top-1/2 -translate-y-1/2 h-11 w-11 items-center justify-center rounded-full border bg-background/90 shadow-md backdrop-blur transition hover:bg-background disabled:opacity-0"
            >
              <ChevronRight className="h-5 w-5" />
            </button>
          </div>

          {/* Controls between slides */}
          <div className="flex items-center gap-3 px-3 sm:px-4 py-3 border-t">
            <button
              type="button"
              onClick={() => go(index - 1)}
              disabled={index === 0}
              aria-label="Previous slide"
              className={cn(buttonVariants({ variant: 'outline', size: 'sm' }), 'shrink-0')}
            >
              <ChevronLeft className="h-4 w-4" />
              <span className="hidden sm:inline">Prev</span>
            </button>

            <div className="flex flex-1 items-center justify-center gap-1.5 flex-wrap" role="tablist" aria-label="Choose slide">
              {SLIDES.map((s, i) => (
                <button
                  key={i}
                  type="button"
                  role="tab"
                  aria-selected={i === index}
                  aria-label={`Slide ${i + 1}: ${s.title}`}
                  onClick={() => go(i)}
                  className={cn(
                    'h-2 rounded-full transition-all',
                    i === index ? 'w-6 bg-primary' : 'w-2 bg-muted-foreground/30 hover:bg-muted-foreground/60',
                  )}
                />
              ))}
            </div>

            <button
              type="button"
              onClick={() => go(index + 1)}
              disabled={index === last}
              aria-label="Next slide"
              className={cn(buttonVariants({ size: 'sm' }), 'shrink-0')}
            >
              <span className="hidden sm:inline">Next</span>
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>
        </section>

        <div
          className="mx-auto mt-5 min-h-[3.5rem]"
          style={{ maxWidth: 'calc((100svh - 150px) * 1270 / 760)' }}
          aria-live="polite"
        >
          <h2 className="font-semibold">{index + 1}. {slide.title}</h2>
          <p className="text-sm text-muted-foreground">{slide.description}</p>
        </div>

        <div className="mt-8 flex flex-col sm:flex-row gap-3">
          <Link
            to="/auth"
            onClick={() => trackEvent('cta_clicked', { label: 'get_started_free', source: 'demo' })}
            className={buttonVariants({ size: 'lg' })}
          >
            Get started free →
          </Link>
          <Link
            to="/docs"
            onClick={() => trackEvent('docs_clicked', { source: 'demo' })}
            className={buttonVariants({ size: 'lg', variant: 'outline' })}
          >
            Read the docs
          </Link>
        </div>
      </div>
    </div>
  )
}
